result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "xlround/reader.py", "content": """"Load a workbook written by xlround.writer back into dicts using the schema."""

from __future__ import annotations

import datetime as _dt
from typing import Any, Mapping

from openpyxl import load_workbook

from .writer import normalize_schema


def _convert(column_type: str, value: Any, colname: str, row_idx: int) -> Any:
    """Convert an openpyxl cell value into the schema-typed python value."""
    if value is None:
        return None  # Nones stay Nones -- never 0, never ""
    try:
        if column_type == "str":
            # Guard against engines that coerce text to dates/numbers.
            if isinstance(value, (_dt.datetime, _dt.date)):
                raise TypeError(f"cell became {type(value).__name__}, expected str")
            return str(value)
        if column_type == "int":
            if isinstance(value, bool):
                raise TypeError("bool cell in int column")
            iv = int(value)
            if iv != float(value):
                raise ValueError(f"non-integral int cell: {value!r}")
            return iv
        if column_type in ("float", "currency", "percent"):
            if isinstance(value, bool):
                raise TypeError("bool cell in numeric column")
            return float(value)
        if column_type == "date":
            if isinstance(value, _dt.datetime):
                return value.date()
            if isinstance(value, _dt.date):
                return value
            raise TypeError(f"expected date cell, got {type(value).__name__}")
        if column_type == "bool":
            if not isinstance(value, bool):
                raise TypeError(f"expected bool cell, got {type(value).__name__}")
            return value
    except (TypeError, ValueError) as exc:
        raise ValueError(
            f"row {row_idx}, column {colname!r} (type {column_type!r}): {exc}"
        ) from exc
    raise ValueError(f"unknown column type {column_type!r}")  # pragma: no cover


def load_workbook(path: str, schema: Any, sheet_name: str | None = None) -> list[dict]:
    """Read ``path`` back into a list of dicts typed per ``schema``.

    Percent columns come back as fractions (matching how writer.py stores
    them); date columns as datetime.date; Nones as None.
    """
    columns = normalize_schema(schema)
    wb = load_workbook(path, data_only=True)
    ws = wb[sheet_name] if sheet_name else wb.active

    header = [c.value for c in ws[1]]
    expected = [col["name"] for col in columns]
    if header[: len(expected)] != expected:
        raise ValueError(
            f"workbook header {header!r} does not match schema columns {expected!r}"
        )

    rows: list[dict] = []
    for r, excel_row in enumerate(
        ws.iter_rows(min_row=2, max_col=len(columns), values_only=True), start=2
    ):
        rows.append(
            {
                col["name"]: _convert(col["type"], val, col["name"], r)
                for col, val in zip(columns, excel_row)
            }
        )
    wb.close()
    return rows
