from __future__ import annotations

import datetime as _dt
import math
from typing import Any, Mapping, Sequence

DEFAULT_FLOAT_TOL = 1e-9


def _is_float_like(v: Any) -> bool:
    return isinstance(v, float) and not isinstance(v, bool)


def compare_value(
    a: Any,
    b: Any,
    ctype: str,
    path: str,
    float_tol: float = DEFAULT_FLOAT_TOL,
) -> list[str]:
    """Compare two values under a schema type; return a list of diff messages."""
    if a is None or b is None:
        if a is None and b is None:
            return []
        kind = "None" if a is None else "value"
        return [f"{path}: original={a!r} roundtripped={b!r} (None-ness mismatch)"]

    if ctype in ("float", "percent", "currency"):
        # percent is stored as a fraction; tolerance applies to the fraction.
        fa, fb = float(a), float(b)
        if math.isclose(fa, fb, rel_tol=float_tol, abs_tol=float_tol):
            return []
        return [
            f"{path}: |{fa!r} - {fb!r}| exceeds tol {float_tol} "
            f"(diff={abs(fa - fb):.3e})"
        ]
    if ctype == "int":
        if isinstance(a, bool) != isinstance(b, bool) or int(a) != int(b):
            return [f"{path}: original={a!r} roundtripped={b!r}"]
        return []
    if ctype == "date":
        da = a.date() if isinstance(a, _dt.datetime) else a
        db = b.date() if isinstance(b, _dt.datetime) else b
        if da != db:
            return [f"{path}: original={da!r} roundtripped={db!r}"]
        return []
    if ctype == "bool":
        if bool(a) != bool(b) or (isinstance(a, bool) != isinstance(b, bool)):
            return [f"{path}: original={a!r} roundtripped={b!r}"]
        return []
    # str and anything else: exact match
    if a != b:
        return [f"{path}: original={a!r} roundtripped={b!r}"]
    return []


def deep_compare(
    original: Sequence[Mapping[str, Any]],
    roundtripped: Sequence[Mapping[str, Any]],
    schema: Any,
    float_tol: float = DEFAULT_FLOAT_TOL,
) -> list[str]:
    """Deep-compare row lists; returns all diffs ([] means equal).

    Type-aware: floats/percents/currencies use ``float_tol``; ints, bools,
    dates and strings are exact; None must round-trip as None.
    """
    from .writer import normalize_schema  # local import to avoid cycles

    columns = {c["name"]: c["type"] for c in normalize_schema(schema)}
    diffs: list[str] = []

    if len(original) != len(roundtripped):
        diffs.append(
            f"row count mismatch: original={len(original)} "
            f"roundtripped={len(roundtripped)}"
        )

    for i, (row_a, row_b) in enumerate(zip(original, roundtripped)):
        missing_a = set(row_a) - set(row_b)
        missing_b = set(row_b) - set(row_a)
        for k in sorted(missing_a):
            diffs.append(f"row {i}: key {k!r} missing from roundtripped")
        for k in sorted(missing_b):
            diffs.append(f"row {i}: key {k!r} missing from original")
        for k in set(row_a) & set(row_b):
            ctype = columns.get(k, "str")
            diffs.extend(
                compare_value(row_a[k], row_b[k], ctype, f"row {i}[{k!r}]", float_tol)
            )
    return diffs


def assert_round_trip(
    original: Sequence[Mapping[str, Any]],
    roundtripped: Sequence[Mapping[str, Any]],
    schema: Any,
    float_tol: float = DEFAULT_FLOAT_TOL,
) -> None:
    """Raise AssertionError listing all diffs if the round trip is lossy."""
    diffs = deep_compare(original, roundtripped, schema, float_tol)
    if diffs:
        preview = "\n".join(diffs[:20])
        more = f"\n... and {len(diffs) - 20} more" if len(diffs) > 20 else ""
        raise AssertionError(f"round-trip mismatch ({len(diffs)} diffs):\n{preview}{more}")
